pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract WhitelistNFT is ERC721, Ownable {
    using Strings for uint256;

    mapping(address => bool) public whitelisted;
    uint256 public constant baseURILength = 40; // length of "ipfs://Qm..."
    bytes32[] private hashedAddresses;
    uint256 private _tokenIds;

    constructor() ERC721("WhitelistNFT", "WLNFT") {}

    modifier onlyOwner() {
        _;
    }

    function addToWhitelist(address[] memory _addresses) public onlyOwner {
        for (uint256 i = 0; i < _addresses.length; i++) {
            whitelisted[_addresses[i]] = true;
            hashedAddresses.push(keccak256(abi.encodePacked(_addresses[i])));
        }
    }

    function removeFromWhitelist(address[] memory _addresses) public onlyOwner {
        for (uint256 i = 0; i < _addresses.length; i++) {
            whitelisted[_addresses[i]] = false;
            uint256 index = findHashedAddressIndex(keccak256(abi.encodePacked(_addresses[i])));
            hashedAddresses[index] = hashedAddresses[hashedAddresses.length - 1];
            hashedAddresses.pop();
        }
    }

    function mint() public payable {
        require(whitelisted[msg.sender], "Not whitelisted");
        _safeMint(msg.sender, baseURI());
        whitelisted[msg.sender] = false;
    }

    function royaltyInfo(uint256 _tokenId, uint256 _salePrice) external view override returns (address receiver, uint256 royaltyAmount) {
        receiver = owner();
        royaltyAmount = _salePrice.div(10); // 10% royalties
    }

    function baseURI() internal view virtual override returns (string memory) {
        return "ipfs://Qm...";
    }

    function tokenURI(uint256 _tokenId) public view override returns (string memory) {
        require(_exists(_tokenId), "ERC721Metadata: URI query for nonexistent token");
        uint256 index = findHashedAddressIndex(keccak256(abi.encodePacked(ownerOf(_tokenId))));
        return string(abi.encodePacked(baseURI(), Strings.toString(index + baseURILength), ".json"));
    }

    function findHashedAddressIndex(bytes32 hashedAddress) private view returns (uint256) {
        for (uint256 i = 0; i < hashedAddresses.length; i++) {
            if (hashedAddresses[i] == hashedAddress) {
                return i;
            }
        }
        revert("Address not found");
    }
}

