pragma solidity ^0.8.0;

import "@openzeppelin/contracts@4.9.3/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts@4.9.3/utils/Strings.sol";
import "@openzeppelin/contracts@4.9.3/access/Ownable.sol";
import "@openzeppelin/contracts@4.9.3/token/ERC721/IERC721Receiver.sol";

contract TokenCraft is ERC1155, Ownable {
    string private baseTokenURI;
    mapping(uint => string) private tokenURIs;

    constructor() ERC1155("", "") {}

    function setBaseTokenURI(string memory _baseTokenURI) external onlyOwner {
        baseTokenURI = _baseTokenURI;
    }

    function mint(address account, uint256 id, uint256 amount, string memory uri)
        external
        onlyOwner
    {
        _mint(account, id, amount, "");
        tokenURIs[id] = uri;
    }

    function batchMint(address to, uint256[] memory ids, uint256[] memory amounts, string memory uri) external onlyOwner {
        require(ids.length == amounts.length, "Ids and amounts length mismatch");
        _mintBatch(to, ids, amounts, "");
        for (uint i = 0; i < ids.length; i++) {
            tokenURIs[ids[i]] = uri;
        }
    }

    function craftToken(uint256[] memory burnIds, uint256[] memory burnAmounts, uint256 newId, string memory uri) external {
        require(burnIds.length == burnAmounts.length, "Ids and amounts length mismatch");
        for (uint i = 0; i < burnIds.length; i++) {
            _burn(msg.sender, burnIds[i], burnAmounts[i]);
        }
        _mint(msg.sender, newId, 1, "");
        tokenURIs[newId] = uri;
    }

    function _beforeTokenTransfer(address operator, address from, address to, uint256[] memory ids, uint256[] memory amounts, bytes calldata data)
        internal
        override
    {
        super._beforeTokenTransfer(operator, from, to, ids, amounts, data);
    }

    function uri(uint256 tokenId) public view virtual override returns (string memory) {
        string memory _uri = baseTokenURI;
        if (tokenURIs[tokenId].length > 0) {
            return string(abi.encodePacked(_uri, Strings.toString(tokenId), "/", tokenURIs[tokenId]));
        } else {
            return super.uri(tokenId);
        }
    }
}

contract Marketplace is Ownable {
    TokenCraft tokenContract;
    mapping(uint => uint) private tokenPrices;
    mapping(uint => address) private tokenOwners;

    constructor(address _tokenContract) {
        tokenContract = TokenCraft(_tokenContract);
    }

    function setTokenPrice(uint tokenId, uint price) external onlyOwner {
        tokenPrices[tokenId] = price;
    }

    function buyToken(uint tokenId) external payable {
        require(address(this).balance >= tokenPrices[tokenId], "Insufficient funds");
        require(tokenOwners[tokenId] == address(0), "Token already sold");
        tokenContract.transferFrom(msg.sender, address(this), tokenId, 1);
        payable(tokenOwners[tokenId]).transfer(tokenPrices[tokenId]);
        tokenOwners[tokenId] = msg.sender;
    }
}

