pragma solidity ^0.8.13;

contract BasicAMM {
    uint256 public tokenBalance;
    uint256 public ethBalance;
    uint256 public constant k = 10**18 * 10**18; // Initial product of ETH and Token (1 ETH = 1 Token)

    function addLiquidity(uint256 _ethAmount, uint256 _tokenAmount) external payable {
        require(_ethAmount > 0 && _tokenAmount > 0, "Invalid input");
        tokenBalance += _tokenAmount;
        ethBalance += msg.value;
    }

    function swap(uint256 _inputAmount, bool _isEth) external payable {
        if (_isEth) {
            require(_inputAmount <= ethBalance && _inputAmount > 0, "Insufficient ETH balance");
            uint256 output = tokenBalance - k / (_inputAmount + ethBalance);
            require(output < tokenBalance && output > 0, "Swap calculation error");
            payable(msg.sender).transfer(tokenBalance - output);
            tokenBalance -= output;
        } else {
            require(_inputAmount <= tokenBalance && _inputAmount > 0, "Insufficient Token balance");
            uint256 output = ethBalance - k / (_inputAmount + tokenBalance);
            require(output < ethBalance && output > 0, "Swap calculation error");
            msg.sender.transfer(ethBalance - output);
            ethBalance -= output;
        }
    }
}

