pragma solidity ^0.8.0;

interface IYieldStrategy {
    function deposit(uint256 amount) external returns (uint256);
    function withdraw(uint256 amount) external returns (uint256);
    function compound() external;
}

contract YieldAggregatorVault {
    address public owner;
    IYieldStrategy public strategy;
    uint256 public depositFeeBps = 10; // 0.1% deposit fee
    uint256 public withdrawalFeeBps = 10; // 0.1% withdrawal fee

    constructor(address _strategy) {
        owner = msg.sender;
        strategy = IYieldStrategy(_strategy);
    }

    function deposit(uint256 amount) public returns (uint256) {
        require(amount > 0, "Amount must be greater than zero");
        uint256 fee = (amount * depositFeeBps) / 10000;
        strategy.deposit(amount - fee);
        return amount - fee;
    }

    function withdraw(uint256 amount) public returns (uint256) {
        uint256 fee = (amount * withdrawalFeeBps) / 10000;
        uint256 withdrawnAmount = strategy.withdraw(amount - fee);
        return withdrawnAmount;
    }

    function compound() public onlyOwner {
        strategy.compound();
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the contract owner can call this function");
        _;
    }
}

