pragma solidity ^0.8.0;

contract SocialRecoveryWallet {
    address payable public owner;
    mapping(address => bool) public guardians;
    uint public requiredGuardians;
    uint public recoveredGuardians;

    constructor(address[] memory _guardians, uint _requiredGuardians) {
        require(_requiredGuardians <= _guardians.length, "Required guardians should not exceed total guardians");
        owner = payable(msg.sender);
        requiredGuardians = _requiredGuardians;

        for (uint i = 0; i < _guardians.length; i++) {
            addGuardian(_guardians[i]);
        }
    }

    function addGuardian(address _guardian) public onlyOwner {
        require(!guardians[_guardian], "Guardian already exists");
        guardians[_guardian] = true;
    }

    function removeGuardian(address _guardian) public onlyOwner {
        require(guardians[_guardian], "Guardian does not exist");
        delete guardians[_guardian];
    }

    function recoverFunds() public {
        require(recoveredGuardians >= requiredGuardians, "Not enough guardians have approved the recovery");
        owner.transfer(address(this).balance);
    }

    function approveRecovery() public {
        require(guardians[msg.sender], "Sender is not a guardian");
        require(recoveredGuardians < requiredGuardians, "All required guardians have already approved the recovery");
        recoveredGuardians++;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only the owner can perform this action");
        _;
    }
}
